#' Agreement Method Guide
#'
#' An educational decision guide across the agreement analysis family. Uses 
#' user-confirmed study design and optional wide or long data inspection to 
#' suggest methods, exact settings, preparation steps and current development 
#' routes. Does not calculate agreement statistics or run another analysis. 
#' Questionnaire guidance works with an empty dataset.
#'
#' @examples
#' agreementintro(data = data.frame(), purpose = "categorical",
#'     scale = "nominal", nRaters = 2, panel = "same",
#'     missingRatings = "no", repeatedReadings = "no",
#'     analysisUnit = "independent")
#' @param data The data as a data frame. Use data.frame() for
#'   questionnaire-only guidance.
#' @param purpose .
#' @param scale .
#' @param nRaters Zero means not specified.
#' @param panel .
#' @param missingRatings .
#' @param repeatedReadings .
#' @param analysisUnit .
#' @param categoryOrder .
#' @param weights .
#' @param raterSelection .
#' @param iccDefinition .
#' @param reportingUnit .
#' @param referenceType .
#' @param comparisonGoal .
#' @param planningGoal .
#' @param nCategories Zero means not specified.
#' @param positiveLabel .
#' @param negativeLabel .
#' @param referencePositive .
#' @param referenceNegative .
#' @param cutoff .
#' @param cutoffDirection .
#' @param cutoffPrespecified .
#' @param inspectData .
#' @param dataLayout .
#' @param ratings .
#' @param conditionBRatings .
#' @param caseID .
#' @param patientID .
#' @param readerID .
#' @param rating .
#' @param condition .
#' @param occasion .
#' @param reference .
#' @param showOverview .
#' @param showRecommendation .
#' @param showExamples .
#' @param showPitfalls .
#' @param showGlossary .
#' @param showCatalogue .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$overview} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$status} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$recommendations} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$settings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$preparation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dataSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$columnSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$inspectionNotes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$examples} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$pitfalls} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$glossary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$catalogue} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$catalogueNotes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$recommendations$asDF}
#'
#' \code{as.data.frame(results$recommendations)}
#'
#' @export
agreementintro <- function(
    data,
    purpose = "unspecified",
    scale = "unspecified",
    nRaters = 0,
    panel = "unspecified",
    missingRatings = "unspecified",
    repeatedReadings = "unspecified",
    analysisUnit = "unspecified",
    categoryOrder = "unspecified",
    weights = "unspecified",
    raterSelection = "unspecified",
    iccDefinition = "unspecified",
    reportingUnit = "unspecified",
    referenceType = "unspecified",
    comparisonGoal = "unspecified",
    planningGoal = "unspecified",
    nCategories = 0,
    positiveLabel = "",
    negativeLabel = "",
    referencePositive = "",
    referenceNegative = "",
    cutoff = "",
    cutoffDirection = "unspecified",
    cutoffPrespecified = "unspecified",
    inspectData = FALSE,
    dataLayout = "wide",
    ratings = NULL,
    conditionBRatings = NULL,
    caseID = NULL,
    patientID = NULL,
    readerID = NULL,
    rating = NULL,
    condition = NULL,
    occasion = NULL,
    reference = NULL,
    showOverview = TRUE,
    showRecommendation = TRUE,
    showExamples = FALSE,
    showPitfalls = FALSE,
    showGlossary = FALSE,
    showCatalogue = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("agreementintro requires jmvcore to be installed (restart may be required)")

    if ( ! missing(ratings)) ratings <- jmvcore::resolveQuo(jmvcore::enquo(ratings))
    if ( ! missing(conditionBRatings)) conditionBRatings <- jmvcore::resolveQuo(jmvcore::enquo(conditionBRatings))
    if ( ! missing(caseID)) caseID <- jmvcore::resolveQuo(jmvcore::enquo(caseID))
    if ( ! missing(patientID)) patientID <- jmvcore::resolveQuo(jmvcore::enquo(patientID))
    if ( ! missing(readerID)) readerID <- jmvcore::resolveQuo(jmvcore::enquo(readerID))
    if ( ! missing(rating)) rating <- jmvcore::resolveQuo(jmvcore::enquo(rating))
    if ( ! missing(condition)) condition <- jmvcore::resolveQuo(jmvcore::enquo(condition))
    if ( ! missing(occasion)) occasion <- jmvcore::resolveQuo(jmvcore::enquo(occasion))
    if ( ! missing(reference)) reference <- jmvcore::resolveQuo(jmvcore::enquo(reference))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(ratings), ratings, NULL),
            `if`( ! missing(conditionBRatings), conditionBRatings, NULL),
            `if`( ! missing(caseID), caseID, NULL),
            `if`( ! missing(patientID), patientID, NULL),
            `if`( ! missing(readerID), readerID, NULL),
            `if`( ! missing(rating), rating, NULL),
            `if`( ! missing(condition), condition, NULL),
            `if`( ! missing(occasion), occasion, NULL),
            `if`( ! missing(reference), reference, NULL))


    options <- agreementintroOptions$new(
        purpose = purpose,
        scale = scale,
        nRaters = nRaters,
        panel = panel,
        missingRatings = missingRatings,
        repeatedReadings = repeatedReadings,
        analysisUnit = analysisUnit,
        categoryOrder = categoryOrder,
        weights = weights,
        raterSelection = raterSelection,
        iccDefinition = iccDefinition,
        reportingUnit = reportingUnit,
        referenceType = referenceType,
        comparisonGoal = comparisonGoal,
        planningGoal = planningGoal,
        nCategories = nCategories,
        positiveLabel = positiveLabel,
        negativeLabel = negativeLabel,
        referencePositive = referencePositive,
        referenceNegative = referenceNegative,
        cutoff = cutoff,
        cutoffDirection = cutoffDirection,
        cutoffPrespecified = cutoffPrespecified,
        inspectData = inspectData,
        dataLayout = dataLayout,
        ratings = ratings,
        conditionBRatings = conditionBRatings,
        caseID = caseID,
        patientID = patientID,
        readerID = readerID,
        rating = rating,
        condition = condition,
        occasion = occasion,
        reference = reference,
        showOverview = showOverview,
        showRecommendation = showRecommendation,
        showExamples = showExamples,
        showPitfalls = showPitfalls,
        showGlossary = showGlossary,
        showCatalogue = showCatalogue)

    analysis <- agreementintroClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

